{
  "target_qa_variants": [
    {
      "language": "en",
      "variant_layer": "core",
      "question": "Which live-action Star Wars series was released in 2022?",
      "expected_answer": "Andor",
      "answer_aliases": [],
      "rewrite_note": "direct core question"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Name the 2022 live-action television series set in the Star Wars universe.",
      "expected_answer": "Andor",
      "answer_aliases": [],
      "rewrite_note": "rephrased as an imperative command"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "What is the title of the Star Wars live-action show that premiered in 2022?",
      "expected_answer": "Andor",
      "answer_aliases": [],
      "rewrite_note": "uses 'show' and 'premiered' instead of 'series' and 'released'"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "In 2022, which live-action series was added to the Star Wars franchise?",
      "expected_answer": "Andor",
      "answer_aliases": [],
      "rewrite_note": "front-loads the year and uses 'added to the franchise'"
    }
  ],
  "neighbor_qa_variants": [
    {
      "language": "en",
      "variant_layer": "core",
      "question": "Which Star Trek prequel series is set a century before the original series?",
      "expected_answer": "Enterprise",
      "answer_aliases": [
        "Star Trek: Enterprise"
      ],
      "rewrite_note": "direct core question"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Name the Star Trek television series that takes place 100 years prior to the original show.",
      "expected_answer": "Enterprise",
      "answer_aliases": [
        "Star Trek: Enterprise"
      ],
      "rewrite_note": "uses '100 years prior' and 'original show' instead of 'a century before'"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "What is the title of the Star Trek prequel show set a century before the original series?",
      "expected_answer": "Enterprise",
      "answer_aliases": [
        "Star Trek: Enterprise"
      ],
      "rewrite_note": "asks for 'title' and uses 'show' instead of 'series'"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Which series in the Star Trek franchise serves as a prequel set 100 years before the original series?",
      "expected_answer": "Enterprise",
      "answer_aliases": [
        "Star Trek: Enterprise"
      ],
      "rewrite_note": "uses 'serves as a prequel' and '100 years'"
    }
  ]
}
